<?php require 'app.php';need_school();$sid=school_id();$err='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();if(!in_array(role(),['director','dos'],true)){http_response_code(403);exit('Forbidden');}try{$q=db()->prepare('INSERT INTO classes(school_id,name,stream) VALUES(?,?,?) ON CONFLICT(school_id,name,stream) DO NOTHING');$q->execute([$sid,trim($_POST['name']),trim($_POST['stream'])]);$err='Class/stream saved.';}catch(Throwable $e){$err=$e->getMessage();}}$sql='SELECT c.*,count(st.id) students FROM classes c LEFT JOIN students st ON st.class_id=c.id AND st.school_id=c.school_id WHERE c.school_id=?';$args=[$sid];if(in_array(role(),['patron','matron'],true)){$ids=assigned_class_ids();$sql.=' AND c.id IN ('.($ids?implode(',',array_fill(0,count($ids),'?')):'NULL').')';$args=array_merge($args,$ids);}$sql.=' GROUP BY c.id ORDER BY c.name,c.stream';$q=db()->prepare($sql);$q->execute($args);$rows=$q->fetchAll();ob_start();?><div class="panel"><h2>Classes and streams</h2><?php if(in_array(role(),['director','dos'],true)):?><form method="post"><input type="hidden" name="_csrf" value="<?=h(csrf())?>"><div class="grid"><label>Class / level<input name="name" placeholder="Senior 4" required></label><label>Stream<input name="stream" placeholder="A, B, Accounting..."></label></div><button>Add class</button></form><?php endif;?><?=h($err)?><table><tr><th>Class</th><th>Stream</th><th>Students</th></tr><?php foreach($rows as $r):?><tr><td><?=h($r['name'])?></td><td><?=h($r['stream'])?></td><td><?=$r['students']?></td></tr><?php endforeach;?></table></div><?php page('Classes and Streams',ob_get_clean());
